{"name":"typec_partner_link_device","qualified_name":"workspace-linux.drivers.usb.typec.class.typec_partner_link_device","label":"Function","file_path":"/workspace/linux/drivers/usb/typec/class.c","start_line":888,"end_line":904,"source":"static void typec_partner_link_device(struct typec_partner *partner, struct device *dev)
{
	int ret;

	ret = sysfs_create_link(&dev->kobj, &partner->dev.kobj, "typec");
	if (ret)
		return;

	ret = sysfs_create_link(&partner->dev.kobj, &dev->kobj, dev_name(dev));
	if (ret) {
		sysfs_remove_link(&dev->kobj, "typec");
		return;
	}

	if (partner->attach)
		partner->attach(partner, dev);
}
